def roman(number):
    values = ((1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'))
    result = ''
    for value, glyph in values:
        while number >= value:
            result += glyph; number -= value
    return result

class ReportDoc(BaseDocTemplate):
    def __init__(self, filename):
        super().__init__(filename, pagesize=A4, leftMargin=2*cm, rightMargin=2*cm, topMargin=2*cm, bottomMargin=2*cm)
        self.frame = Frame(self.leftMargin, self.bottomMargin, self.width, self.height, id='normal')
        self.addPageTemplates(PageTemplate(id='report', frames=[self.frame], onPage=self.footer))
    def afterFlowable(self, flowable):
        if isinstance(flowable, Paragraph):
            style = flowable.style.name
            if style == 'Chapter': self.notify('TOCEntry', (0, flowable.getPlainText(), self.page))
            elif style == 'SectionHeading': self.notify('TOCEntry', (1, flowable.getPlainText(), self.page))
    def footer(self, canvas, doc):
        if doc.page == 1: return
        canvas.saveState(); canvas.setFont('Times-Roman', 9)
        canvas.setStrokeColor(colors.black); canvas.setLineWidth(.35)
        canvas.line(2*cm, 1.55*cm, A4[0]-2*cm, 1.55*cm)
        label = roman(doc.page - 1).lower() if doc.page <= 10 else str(doc.page - 10)
        canvas.drawCentredString(A4[0]/2, 1.03*cm, label)
        canvas.restoreState()

