def grid(data, widths, header=True, size=9.1):
    d = [[x if isinstance(x, Paragraph) else P(str(x), 'Small') for x in row] for row in data]
    tab = Table(d, colWidths=widths, repeatRows=1 if header else 0, hAlign='LEFT')
    style=[('GRID',(0,0),(-1,-1),.45,colors.black),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),('FONTSIZE',(0,0),(-1,-1),size)]
    if header: style += [('BACKGROUND',(0,0),(-1,0),colors.lightgrey),('FONTNAME',(0,0),(-1,0),'Times-Bold')]
    tab.setStyle(TableStyle(style)); return tab
def fig_flow(label, boxes):
    row=[P('<b>'+x[0]+'</b><br/>'+x[1], 'Small') for x in boxes]
    t=Table([row], colWidths=[16.5*cm/len(boxes)]*len(boxes))
    t.setStyle(TableStyle([('GRID',(0,0),(-1,-1),.7,colors.black),('BACKGROUND',(0,0),(-1,-1),colors.HexColor('#F2F2F2')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('ALIGN',(0,0),(-1,-1),'CENTER'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),10),('BOTTOMPADDING',(0,0),(-1,-1),10)]))
    return [t, P(label, 'Caption')]

